1	//! Translate core `Item`s into Gemini `contents` + `systemInstruction`.
2	
3	use crate::PROVIDER_DATA_KEY;
4	use paigasus_helikon_core::{ContentPart, Item, MediaSource, ModelError};
5	use serde_json::{json, Value};
6	use std::collections::HashSet;
7	
8	/// The dummy thought signature for a `functionCall` part that has no valid
9	/// signature in the current turn.
10	///
11	/// Source: this is the dummy value that Google documents for a history with
12	/// no signature. The SMA-820 probe and the SMA-827 probe (capture 6) got
13	/// HTTP 200 with it on `gemini-3.8-flash` (Developer API). Google warns that
14	/// the dummy can make answers worse, so the translator uses it only as the
15	/// fallback.
16	pub(crate) const DUMMY_THOUGHT_SIGNATURE: &str = "skip_thought_signature_validator";
17	
18	/// `contents` + optional `systemInstruction`.
19	pub(crate) struct TranslatedContents {
20	    pub(crate) system: Option<Value>,
21	    pub(crate) contents: Vec<Value>,
22	}
23	
24	/// Tracks tool calls that have no result yet, so each result takes its name
25	/// from the earliest open call with the same id (FIFO). Gemini ids are only
26	/// unique within one response, so ids can repeat across turns.
27	struct OpenCalls<'a> {
28	    /// `(call_id, name)` in open order.
29	    open: Vec<(&'a str, &'a str)>,
30	    /// Ids opened so far.
31	    seen: HashSet<&'a str>,
32	    /// Ids of every call in the conversation (error-message choice only).
33	    all: HashSet<&'a str>,
34	}
35	
36	impl<'a> OpenCalls<'a> {
37	    fn new(items: &'a [Item]) -> Self {
38	        let mut all = HashSet::new();
39	        for it in items {
40	            match it {
41	                Item::ToolCall { call_id, .. } => {
42	                    all.insert(call_id.as_str());
43	                }
44	                Item::AssistantMessage { content, .. } => {
45	                    for p in content {
46	                        if let ContentPart::ToolUse { call_id, .. } = p {
47	                            all.insert(call_id.as_str());
48	                        }
49	                    }
50	                }
51	                _ => {}
52	            }
53	        }
54	        Self {
55	            open: Vec::new(),
56	            seen: HashSet::new(),
57	            all,
58	        }
59	    }
60	
61	    fn open(&mut self, call_id: &'a str, name: &'a str) {
62	        self.seen.insert(call_id);
63	        self.open.push((call_id, name));
64	    }
65	
66	    /// `Ok(Some(name))` closes the earliest open call with this id. `Ok(None)`
67	    /// means a duplicate result: the caller drops it.
68	    fn close(&mut self, call_id: &str) -> Result<Option<&'a str>, ModelError> {
69	        if let Some(pos) = self.open.iter().position(|(id, _)| *id == call_id) {
70	            return Ok(Some(self.open.remove(pos).1));
71	        }
72	        if self.seen.contains(call_id) {
73	            tracing::warn!(
74	                target: "paigasus::gemini::translate",
75	                call_id,
76	                "tool result closes no open call; dropping"
77	            );
78	            return Ok(None);
79	        }
80	        if self.all.contains(call_id) {
81	            Err(ModelError::Other(anyhow::anyhow!(
82	                "tool result for call_id {call_id} comes before its call"
83	            )))
84	        } else {
85	            Err(ModelError::Other(anyhow::anyhow!(
86	                "tool result references unknown call_id {call_id}"
87	            )))
88	        }
89	    }
90	}
91	
92	/// One wire part, with side data that never goes on the wire.
93	struct Part {
94	    json: Value,
95	    /// The position of a `functionCall` in the model response that the stream
96	    /// recorded. `None` for every other part, and for a call with no data.
97	    index: Option<u64>,
98	}
99	
100	impl Part {
101	    fn plain(json: Value) -> Self {
102	        Self { json, index: None }
103	    }
104	
105	    fn is_call(&self) -> bool {
106	        self.json.get("functionCall").is_some()
107	    }
108	
109	    fn is_response(&self) -> bool {
110	        self.json.get("functionResponse").is_some()
111	    }
112	}
113	
114	/// The Gemini provider data of the latest `AssistantMessage`, as
115	/// `(call_id, data)`. Each `functionCall` takes and removes the first entry
116	/// with its id.
117	struct Pending<'a> {
118	    entries: Vec<(&'a str, &'a Value)>,
119	    model_id: &'a str,
120	    api: &'a str,
121	}
122	
123	impl<'a> Pending<'a> {
124	    /// Replace the list with the Gemini provider data of one message.
125	    fn load(&mut self, content: &'a [ContentPart]) {
126	        self.entries = content
127	            .iter()
128	            .filter_map(|p| match p {
129	                ContentPart::ProviderData {
130	                    provider,
131	                    call_id: Some(call_id),
132	                    data,
133	                } if provider == PROVIDER_DATA_KEY => Some((call_id.as_str(), data)),
134	                _ => None,
135	            })
136	            .collect();
137	    }
138	
139	    fn clear(&mut self) {
140	        self.entries.clear();
141	    }
142	
143	    /// Build the `functionCall` part for one call. A valid signature goes on
144	    /// the part. The stream index goes into the side data.
145	    fn function_call(&mut self, call_id: &str, name: &str, args: &Value) -> Part {
146	        let data = self
147	            .entries
148	            .iter()
149	            .position(|(id, _)| *id == call_id)
150	            .map(|pos| self.entries.remove(pos).1);
151	        let mut json = json!({ "functionCall": { "id": call_id, "name": name, "args": args } });
152	        if let Some(sig) = data.and_then(|d| self.valid_signature(d)) {
153	            json["thoughtSignature"] = Value::String(sig.to_owned());
154	        }
155	        Part {
156	            json,
157	            index: data.and_then(|d| d.get("index")).and_then(Value::as_u64),
158	        }
159	    }
160	
161	    /// The signature in `data` when it is a non-empty string and `data` names
162	    /// this model and this API. Anything else is no signature, never an error.
163	    fn valid_signature<'d>(&self, data: &'d Value) -> Option<&'d str> {
164	        let sig = data.get("thoughtSignature")?.as_str()?;
165	        (!sig.is_empty()
166	            && data.get("model").and_then(Value::as_str) == Some(self.model_id)
167	            && data.get("api").and_then(Value::as_str) == Some(self.api))
168	        .then_some(sig)
169	    }
170	}
171	
172	/// Translate core items into Gemini `contents`. Returns an error on an empty
173	/// or system-only conversation (Gemini 400s on empty contents).
174	///
175	/// `model_id` and `api` are the configured model and transport. A thought
176	/// signature goes back only when its provider data names both.
177	pub(crate) fn items_to_contents(
178	    items: &[Item],
179	    model_id: &str,
180	    api: &str,
181	) -> Result<TranslatedContents, ModelError> {
182	    let mut calls = OpenCalls::new(items);
183	    let mut pending = Pending {
184	        entries: Vec::new(),
185	        model_id,
186	        api,
187	    };
188	    let mut system_parts: Vec<Value> = Vec::new();
189	    let mut entries: Vec<(&'static str, Vec<Part>)> = Vec::new();
190	
191	    for it in items {
192	        match it {
193	            Item::System { content } => {
194	                system_parts.extend(text_parts(content));
195	            }
196	            Item::UserMessage { content } => {
197	                let parts = user_parts(content, &mut calls)?;
198	                // Only a wire part that is not a tool result ends the model
199	                // response. Tool results and parts that emit nothing keep the
200	                // pending list.
201	                if parts.iter().any(|p| p.get("functionResponse").is_none()) {
202	                    pending.clear();
203	                }
204	                entries.push(("user", parts.into_iter().map(Part::plain).collect()));
205	            }
206	            Item::AssistantMessage { content, .. } => {
207	                pending.load(content);
208	                for p in content {
209	                    if let ContentPart::ToolUse { call_id, name, .. } = p {
210	                        calls.open(call_id, name);
211	                    }
212	                }
213	                entries.push(("model", assistant_parts(content, &mut pending)));
214	            }
215	            Item::ToolCall {
216	                call_id,
217	                name,
218	                args,
219	            } => {
220	                calls.open(call_id, name);
221	                entries.push(("model", vec![pending.function_call(call_id, name, args)]));
222	            }
223	            Item::ToolResult { call_id, content } => {
224	                if let Some(name) = calls.close(call_id)? {
225	                    entries.push((
226	                        "user",
227	                        vec![Part::plain(json!({
228	                            "functionResponse": {
229	                                "id": call_id,
230	                                "name": name,
231	                                "response": tool_response_object(content),
232	                            }
233	                        }))],
234	                    ));
235	                }
236	            }
237	            _ => {}
238	        }
239	    }
240	
241	    let mut merged = merge_same_role(entries);
242	    for i in 0..merged.len() {
243	        if merged[i].0 == "model" && restore_call_order(&mut merged[i].1) {
244	            let ids = call_ids(&merged[i].1);
245	            if let Some((role, next)) = merged.get_mut(i + 1) {
246	                if *role == "user" {
247	                    order_responses(next, &ids);
248	                }
249	            }
250	        }
251	    }
252	    if is_gemini_3_or_later(model_id) {
253	        add_dummy_signatures(&mut merged);
254	    }
255	    let contents: Vec<Value> = merged
256	        .into_iter()
257	        .map(|(role, parts)| {
258	            let parts: Vec<Value> = parts.into_iter().map(|p| p.json).collect();
259	            json!({ "role": role, "parts": parts })
260	        })
261	        .collect();
262	    let mut contents = contents;
263	    if is_gemini_3_or_later(model_id) && contents.last().is_some_and(|c| c["role"] == "model") {
264	        contents.push(json!({
265	            "role": "user",
266	            "parts": [{ "text": TRAILING_MODEL_TURN_PROMPT }],
267	        }));
268	    }
269	    if contents.is_empty() {
270	        return Err(ModelError::Other(anyhow::anyhow!(
271	            "gemini request has no user/model turns (empty or system-only conversation)"
272	        )));
273	    }
274	
275	    let system = (!system_parts.is_empty()).then(|| json!({ "parts": system_parts }));
276	    Ok(TranslatedContents { system, contents })
277	}
278	
279	/// Merge adjacent entries of the same role into one content, in order.
280	///
281	/// Two `user` entries merge only when both hold only `functionResponse` parts
282	/// or both hold none. Gemini 3 starts the current turn at the last `user`
283	/// content that is not a tool result, and it checks thought signatures only in
284	/// that turn. SMA-820 added this boundary because a text and a
285	/// `functionResponse` in one content kept an unsigned `functionCall` in the
286	/// current turn, and Gemini returned HTTP 400. The SMA-827 probe (capture 8)
287	/// got HTTP 200 for the merged shape with the real signature, so the boundary
288	/// is not needed when signatures are present. It stays until Sven decides; see
289	/// the SMA-827 spec section "Left for Sven". A content that mixes results and
290	/// other parts merges with nothing, so a later text never joins a tool result.
291	/// An entry with no parts is dropped first, so it never emits `"parts": []`.
292	fn merge_same_role(entries: Vec<(&'static str, Vec<Part>)>) -> Vec<(&'static str, Vec<Part>)> {
293	    #[derive(PartialEq, Clone, Copy)]
294	    enum Class {
295	        AllResponses,
296	        NoResponses,
297	        Mixed,
298	    }
299	    let class = |parts: &[Part]| {
300	        let n = parts.iter().filter(|p| p.is_response()).count();
301	        if n == parts.len() {
302	            Class::AllResponses
303	        } else if n == 0 {
304	            Class::NoResponses
305	        } else {
306	            Class::Mixed
307	        }
308	    };
309	    // Each merged entry keeps its class, so a merge never rescans the parts.
310	    let mut merged: Vec<(&'static str, Class, Vec<Part>)> = Vec::new();
311	    for (role, parts) in entries {
312	        if parts.is_empty() {
313	            continue;
314	        }
315	        let incoming = class(&parts);
316	        match merged.last_mut() {
317	            // A merge needs equal classes that are not `Mixed`, so the stored
318	            // class stays correct after it.
319	            Some((last_role, last_class, last_parts))
320	                if *last_role == role
321	                    && (role != "user"
322	                        || (*last_class != Class::Mixed && *last_class == incoming)) =>
323	            {
324	                last_parts.extend(parts)
325	            }
326	            _ => merged.push((role, incoming, parts)),
327	        }
328	    }
329	    merged
330	        .into_iter()
331	        .map(|(role, _, parts)| (role, parts))
332	        .collect()
333	}
334	
335	/// Sort the `functionCall` parts of one `model` content by their stream index,
336	/// when every call has one. The sort is stable, and the other parts keep their
337	/// positions. This restores the order that Gemini sent. Returns `true` when
338	/// every call has an index, whether or not the order changed. The caller then
339	/// orders the responses to match. Returns `false` when there is no call or a
340	/// call has no index.
341	fn restore_call_order(parts: &mut [Part]) -> bool {
342	    let slots: Vec<usize> = (0..parts.len()).filter(|&i| parts[i].is_call()).collect();
343	    if slots.is_empty() || slots.iter().any(|&i| parts[i].index.is_none()) {
344	        return false;
345	    }
346	    if slots
347	        .windows(2)
348	        .all(|w| parts[w[0]].index <= parts[w[1]].index)
349	    {
350	        return true;
351	    }
352	    let mut calls: Vec<Part> = slots
353	        .iter()
354	        .map(|&i| std::mem::replace(&mut parts[i], Part::plain(Value::Null)))
355	        .collect();
356	    calls.sort_by_key(|p| p.index);
357	    for (slot, part) in slots.into_iter().zip(calls) {
358	        parts[slot] = part;
359	    }
360	    true
361	}
362	
363	/// The `functionCall` ids of one content, in order.
364	fn call_ids(parts: &[Part]) -> Vec<String> {
365	    parts
366	        .iter()
367	        .filter_map(|p| p.json["functionCall"]["id"].as_str().map(str::to_owned))
368	        .collect()
369	}
370	
371	/// Sort the `functionResponse` parts of one `user` content into the order of
372	/// `ids`, so the responses follow the calls. The sort is stable. A response
373	/// whose id is not in `ids` goes after the matched ones. The other parts keep
374	/// their positions.
375	fn order_responses(parts: &mut [Part], ids: &[String]) {
376	    let slots: Vec<usize> = (0..parts.len())
377	        .filter(|&i| parts[i].is_response())
378	        .collect();
379	    let mut responses: Vec<Part> = slots
380	        .iter()
381	        .map(|&i| std::mem::replace(&mut parts[i], Part::plain(Value::Null)))
382	        .collect();
383	    // A repeated id in `ids` matches its first position; the stable sort keeps
384	    // the history order of such responses.
385	    responses.sort_by_key(|p| {
386	        let id = p.json["functionResponse"]["id"].as_str();
387	        ids.iter()
388	            .position(|c| Some(c.as_str()) == id)
389	            .unwrap_or(ids.len())
390	    });
391	    for (slot, part) in slots.into_iter().zip(responses) {
392	        parts[slot] = part;
393	    }
394	}
395	
396	/// Say whether `model_id` is Gemini 3 or later. Such a request may carry
397	/// [`DUMMY_THOUGHT_SIGNATURE`] and may get a [`TRAILING_MODEL_TURN_PROMPT`] turn.
398	///
399	/// The dummy is live-tested only on Gemini 3. Requests for a Gemini 1.x or
400	/// 2.x id stay as they were before SMA-827 and get no dummy. Every other id
401	/// (Gemini 3 and later, unknown ids) gets it. The check uses the part of the id
402	/// after the last `/`, so `models/gemini-2.5-flash` and Vertex resource paths work.
403	fn is_gemini_3_or_later(model_id: &str) -> bool {
404	    let name = model_id.rsplit('/').next().unwrap_or(model_id);
405	    !(name.starts_with("gemini-1") || name.starts_with("gemini-2"))
406	}
407	
408	/// Text of the `user` turn that follows a trailing `model` turn.
409	///
410	/// Gemini rejects a request whose last turn is a model turn. The core
411	/// structured-output finalizing request ends with the model's own answer, so
412	/// the translator appends this turn for Gemini 3 and later.
413	pub(crate) const TRAILING_MODEL_TURN_PROMPT: &str = "Continue.";
414	
415	/// Put [`DUMMY_THOUGHT_SIGNATURE`] on each `functionCall` part of a `model`
416	/// content in the current turn when none of its calls has a signature.
417	///
418	/// The current turn is every content after the last `user` content with no
419	/// `functionResponse` part (all contents when there is no such content).
420	/// Gemini checks signatures only in that turn. A content with at least one
421	/// signature is sent as received.
422	fn add_dummy_signatures(merged: &mut [(&'static str, Vec<Part>)]) {
423	    let start = merged
424	        .iter()
425	        .rposition(|(role, parts)| *role == "user" && !parts.iter().any(Part::is_response))
426	        .map_or(0, |i| i + 1);
427	    for (role, parts) in &mut merged[start..] {
428	        if *role != "model" {
429	            continue;
430	        }
431	        let has_call = parts.iter().any(Part::is_call);
432	        let has_signature = parts
433	            .iter()
434	            .any(|p| p.is_call() && p.json.get("thoughtSignature").is_some());
435	        if !has_call || has_signature {
436	            continue;
437	        }
438	        for p in parts.iter_mut().filter(|p| p.is_call()) {
439	            p.json["thoughtSignature"] = Value::String(DUMMY_THOUGHT_SIGNATURE.to_owned());
440	        }
441	    }
442	}
443	
444	fn text_parts(content: &[ContentPart]) -> Vec<Value> {
445	    content
446	        .iter()
447	        .filter_map(|p| match p {
448	            ContentPart::Text { text } => Some(json!({ "text": text })),
449	            _ => None,
450	        })
451	        .collect()
452	}
453	
454	/// Translate the parts of an `Item::UserMessage`.
455	///
456	/// Handles the Anthropic-native [`ContentPart::ToolResult`] shape (a tool
457	/// result carried inside a user turn) by emitting a `functionResponse` part,
458	/// recovering the function name from the earliest open call with that id
459	/// exactly like the top-level [`Item::ToolResult`] branch. A duplicate result
460	/// (no open call left) is dropped with a warning. Text and base64 images translate as usual;
461	/// URL images and other parts are dropped with a discriminant warning.
462	fn user_parts<'a>(
463	    content: &'a [ContentPart],
464	    calls: &mut OpenCalls<'a>,
465	) -> Result<Vec<Value>, ModelError> {
466	    let mut out = Vec::new();
467	    for p in content {
468	        match p {
469	            // The translator drops empty text, as SMA-804 spec section 5.3
470	            // asks every translator to do.
471	            ContentPart::Text { text } if text.is_empty() => {}
472	            ContentPart::Text { text } => out.push(json!({ "text": text })),
473	            ContentPart::Image {
474	                source: MediaSource::Base64 { mime_type, data },
475	            } => {
476	                out.push(json!({ "inlineData": { "mimeType": mime_type, "data": data } }));
477	            }
478	            // Provider data is valid only in an assistant message.
479	            ContentPart::ProviderData { .. } => {}
480	            ContentPart::ToolResult { call_id, content } => {
481	                if let Some(name) = calls.close(call_id)? {
482	                    out.push(json!({
483	                        "functionResponse": {
484	                            "id": call_id,
485	                            "name": name,
486	                            "response": tool_response_object(content),
487	                        }
488	                    }));
489	                }
490	            }
491	            other => {
492	                tracing::warn!(
493	                    target: "paigasus::gemini::translate",
494	                    part = ?std::mem::discriminant(other),
495	                    "unsupported content part; skipping"
496	                );
497	            }
498	        }
499	    }
500	    Ok(out)
501	}
502	
503	/// Translate the parts of an `Item::AssistantMessage`. A `ToolUse` part takes
504	/// its provider data from `pending`. A `ProviderData` part is never a wire
505	/// part: the caller read the Gemini ones into `pending`, and a foreign one is
506	/// ignored with no warning.
507	fn assistant_parts(content: &[ContentPart], pending: &mut Pending<'_>) -> Vec<Part> {
508	    let mut out = Vec::new();
509	    for p in content {
510	        match p {
511	            ContentPart::Text { text } if text.is_empty() => {}
512	            ContentPart::Text { text } => out.push(Part::plain(json!({ "text": text }))),
513	            ContentPart::ToolUse {
514	                call_id,
515	                name,
516	                args,
517	            } => {
518	                out.push(pending.function_call(call_id, name, args));
519	            }
520	            ContentPart::ProviderData { .. } => {}
521	            ContentPart::Reasoning { .. } => { /* deferred (D3) */ }
522	            other => {
523	                tracing::warn!(
524	                    target: "paigasus::gemini::translate",
525	                    part = ?std::mem::discriminant(other),
526	                    "unsupported assistant part; skipping"
527	                );
528	            }
529	        }
530	    }
531	    out
532	}
533	
534	/// Reduce a tool result's content parts to a JSON object for `functionResponse.response`.
535	fn tool_response_object(content: &[ContentPart]) -> Value {
536	    let text: String = content
537	        .iter()
538	        .filter_map(|p| match p {
539	            ContentPart::Text { text } => Some(text.as_str()),
540	            _ => None,
541	        })
542	        .collect::<Vec<_>>()
543	        .join("");
544	    match serde_json::from_str::<Value>(&text) {
545	        Ok(Value::Object(m)) => Value::Object(m),
546	        Ok(other) => json!({ "result": other }),
547	        Err(_) => json!({ "result": text }),
548	    }
549	}
550	
551	#[cfg(test)]
552	mod tests {
553	    use super::*;
554	
555	    const M: &str = "gemini-3.8-flash";
556	    const A: &str = "developer";
557	
558	    fn user(s: &str) -> Item {
559	        Item::UserMessage {
560	            content: vec![ContentPart::Text { text: s.into() }],
561	        }
562	    }
563	
564	    #[test]
565	    fn system_goes_to_system_instruction_not_contents() {
566	        let items = vec![
567	            Item::System {
568	                content: vec![ContentPart::Text {
569	                    text: "be terse".into(),
570	                }],
571	            },
572	            user("hi"),
573	        ];
574	        let t = items_to_contents(&items, M, A).unwrap();
575	        assert_eq!(t.system.unwrap()["parts"][0]["text"], "be terse");
576	        assert_eq!(t.contents.len(), 1);
577	        assert_eq!(t.contents[0]["role"], "user");
578	        assert_eq!(t.contents[0]["parts"][0]["text"], "hi");
579	    }
