447	                    recorder.observe(&AgentEvent::MessageOutput { item: item.clone() })
448	                }
449	                Item::ToolCall { .. } => {
450	                    recorder.observe(&AgentEvent::ToolCallItem { item: item.clone() })
451	                }
452	                _ => {}
453	            }
454	        }
