1	//! SSE -> ModelEvent translation tests via a mock server.
2	
3	use futures_util::StreamExt;
4	use paigasus_helikon_core::{
5	    CancellationToken, ContentPart, FinishReason, Item, Model, ModelError, ModelEvent, ModelRequest,
6	};
7	use paigasus_helikon_providers_gemini::GeminiModel;
8	use wiremock::matchers::method;
9	use wiremock::{Mock, MockServer, ResponseTemplate};
10	
11	async fn run(sse: &'static str) -> Vec<Result<ModelEvent, ModelError>> {
12	    let server = MockServer::start().await;
13	    Mock::given(method("POST"))
14	        .respond_with(
15	            ResponseTemplate::new(200)
16	                .insert_header("content-type", "text/event-stream")
17	                .set_body_raw(sse, "text/event-stream"),
18	        )
19	        .mount(&server)
20	        .await;
21	    let model = GeminiModel::developer("gemini-2.5-flash")
22	        .api_key("k")
23	        .base_url(server.uri())
24	        .build()
25	        .unwrap();
26	    let mut r = ModelRequest::new();
27	    r.messages = vec![Item::UserMessage {
28	        content: vec![ContentPart::Text { text: "hi".into() }],
29	    }];
30	    let mut s = model.invoke(r, CancellationToken::new()).await.unwrap();
31	    let mut out = Vec::new();
32	    while let Some(ev) = s.next().await {
33	        out.push(ev);
34	    }
35	    out
36	}
37	
38	#[tokio::test]
39	async fn text_then_finish() {
40	    let evs = run("data: {\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"a\"}]},\"finishReason\":\"STOP\"}],\"usageMetadata\":{\"promptTokenCount\":1,\"candidatesTokenCount\":1}}\n\n").await;
41	    assert!(matches!(evs.first().unwrap(), Ok(ModelEvent::TokenDelta { text }) if text == "a"));
42	    assert!(evs.iter().any(|e| matches!(
43	        e,
44	        Ok(ModelEvent::Finish {
45	            reason: FinishReason::Stop
46	        })
47	    )));
48	}
49	
50	#[tokio::test]
51	async fn blocked_prompt_refused() {
52	    let evs = run("data: {\"promptFeedback\":{\"blockReason\":\"SAFETY\"}}\n\n").await;
53	    assert!(matches!(
54	        evs.first().unwrap(),
55	        Err(ModelError::Refused { .. })
56	    ));
57	}
58	
59	#[tokio::test]
60	async fn truncated_stream_no_finish() {
61	    let evs =
62	        run("data: {\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"partial\"}]}}]}\n\n")
63	            .await;
64	    assert!(evs
65	        .iter()
66	        .all(|e| !matches!(e, Ok(ModelEvent::Finish { .. }))));
67	}
68	
69	/// Documents the actual per-chunk `Usage` emission behavior.
70	///
71	/// The `StreamTranslator` emits one `ModelEvent::Usage` per SSE chunk that
72	/// carries `usageMetadata`. This test exercises a two-chunk stream where both
73	/// chunks include usage data, confirming that the stream yields exactly two
74	/// `Usage` events (one per chunk). Consumers tracking cumulative token counts
75	/// should use the **last** `Usage` seen within a turn, per the last-wins
76	/// contract documented in `ModelEvent::Usage`.
77	#[tokio::test]
78	async fn multi_chunk_usage_emits_usage_per_chunk() {
79	    // Two SSE events, both carrying usageMetadata.
80	    // Chunk 1: text "a" + usage (promptTokens=1, candidateTokens=1).
81	    // Chunk 2: text "b" + STOP finishReason + usage (promptTokens=1, candidateTokens=2).
82	    let evs = run(concat!(
83	        "data: {\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"a\"}]}}],",
84	        "\"usageMetadata\":{\"promptTokenCount\":1,\"candidatesTokenCount\":1}}\n\n",
85	        "data: {\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"b\"}]},\"finishReason\":\"STOP\"}],",
86	        "\"usageMetadata\":{\"promptTokenCount\":1,\"candidatesTokenCount\":2}}\n\n",
87	    ))
88	    .await;
89	
90	    let usage_count = evs
91	        .iter()
92	        .filter(|e| matches!(e, Ok(ModelEvent::Usage { .. })))
93	        .count();
94	
95	    // StreamTranslator emits one Usage per SSE chunk that includes usageMetadata,
96	    // so two chunks with usageMetadata produce two Usage events.
97	    assert_eq!(
98	        usage_count, 2,
99	        "expected one Usage event per SSE chunk carrying usageMetadata; got {usage_count}"
100	    );
101	}
102	
103	/// A real capture of three parallel calls: only the first part is signed.
104	#[tokio::test]
105	async fn parallel_signed_fixture_emits_provider_data_per_call() {
106	    let evs = run(include_str!("fixtures/parallel_signed.sse")).await;
107	    let data: Vec<(Option<String>, serde_json::Value)> = evs
108	        .iter()
109	        .filter_map(|e| match e {
110	            Ok(ModelEvent::ProviderData {
111	                provider,
112	                call_id,
113	                data,
114	            }) => {
115	                assert_eq!(provider, "gemini");
116	                Some((call_id.clone(), data.clone()))
117	            }
118	            _ => None,
119	        })
120	        .collect();
121	    let calls: Vec<String> = evs
122	        .iter()
123	        .filter_map(|e| match e {
124	            Ok(ModelEvent::ToolCallDelta { call_id, .. }) => Some(call_id.clone()),
125	            _ => None,
126	        })
127	        .collect();
128	    assert_eq!(data.len(), 3);
129	    assert_eq!(calls.len(), 3);
130	    for (i, (call_id, d)) in data.iter().enumerate() {
131	        assert_eq!(call_id.as_deref(), Some(calls[i].as_str()));
