11	fn sse_ok() -> ResponseTemplate {
12	    ResponseTemplate::new(200)
13	        .insert_header("content-type", "text/event-stream")
14	        .set_body_raw(
15	            "data: {\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"hi\"}]},\"finishReason\":\"STOP\"}],\"usageMetadata\":{\"promptTokenCount\":1,\"candidatesTokenCount\":1}}\n\n",
16	            "text/event-stream",
17	        )
18	}
