20	fn user(s: &str) -> ModelRequest {
21	    let mut r = ModelRequest::new();
22	    r.messages = vec![Item::UserMessage {
23	        content: vec![ContentPart::Text { text: s.into() }],
24	    }];
25	    r
26	}
