28	#[tokio::test]
29	async fn developer_url_and_api_key_header() {
30	    let server = MockServer::start().await;
31	    Mock::given(method("POST"))
32	        .and(path(
33	            "/v1beta/models/gemini-2.5-flash:streamGenerateContent",
34	        ))
35	        .and(query_param("alt", "sse"))
36	        .and(header("x-goog-api-key", "sk-test"))
37	        .respond_with(sse_ok())
38	        .mount(&server)
39	        .await;
40	
41	    let model = GeminiModel::developer("gemini-2.5-flash")
42	        .api_key("sk-test")
43	        .base_url(server.uri())
44	        .build()
45	        .unwrap();
46	    let mut s = model
47	        .invoke(user("hi"), CancellationToken::new())
48	        .await
49	        .unwrap();
50	    let mut texts = Vec::new();
51	    while let Some(ev) = s.next().await {
52	        if let Ok(paigasus_helikon_core::ModelEvent::TokenDelta { text }) = ev {
53	            texts.push(text);
54	        }
55	    }
56	    assert_eq!(texts, vec!["hi"]);
57	}
